css:
.surface { border-radius: 8px; padding: 14px; border: 1px solid #334155; background: #111827; color: #f8fafc; transition: background 180ms ease, color 180ms ease; }
#sandbox-root.scheme-light .surface { background: #f8fafc; color: #0f172a; border-color: #cbd5e1; }
#sandbox-root.pref-forced-colors .surface { background: #000000; color: #ffffff; border: 2px solid #ffffff; }
.head { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.dot { width: 10px; height: 10px; border-radius: 50%; background: #38bdf8; animation: pulseSlide 1.1s ease-in-out infinite alternate; }
@keyframes pulseSlide { from { transform: translateX(0) scale(1); } to { transform: translateX(6px) scale(1.25); } }
#sandbox-root.pref-reduce-motion .dot { animation: none; opacity: 0.9; }
#sandbox-root.pref-forced-colors .dot { background: #ffff00; }
.tag { margin-left: auto; font-size: 11px; opacity: 0.8; }
.copy { margin: 0 0 12px; font-size: 12px; opacity: 0.88; }
.actions { display: flex; gap: 8px; flex-wrap: wrap; }
.btn-safe, .btn-unsafe { padding: 6px 10px; border-radius: 6px; font-size: 11px; font-weight: 600; cursor: pointer; }
.btn-safe { background: #0284c7; color: #ffffff; border: 1px solid transparent; }
.btn-unsafe { background: #334155; color: #f8fafc; border: none; }
#sandbox-root.scheme-light .btn-unsafe { background: #e2e8f0; color: #0f172a; }
#sandbox-root.pref-forced-colors .btn-safe { background: #000000; color: #ffff00; border: 2px solid #ffff00; }
#sandbox-root.pref-forced-colors .btn-unsafe { background: #000000; color: #ffffff; border: none; outline: none; }
